window.__CAT__=window.__CAT__||[];window.__CAT__.push([{"no": 118, "id": "AF-IDhifQz8", "title": "【Lの女性向音声】小乔老师 一", "title_zh": "小乔老师 一", "duration": "00:05:50", "link": "https://www.youtube.com/watch?v=AF-IDhifQz8", "enriched": true, "lines": [{"ts": "00:00:00", "text": "晚安。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:06", "text": "你还没回去？", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:12", "text": "好。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:19", "text": "齐老师。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:22", "text": "怎么了？", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:26", "text": "尽管问吧。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:30", "text": "像乔老师这么温柔，又是新面孔，被学生欺负也很正常。", "speaker": "老师", "tone": "责备", "sound": []}, {"ts": "00:00:40", "text": "其实，我们做老师呢，对学生就是要严厉。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:50", "text": "明天开始，要不这样，你过来。", "speaker": "老师", "tone": "命令", "sound": []}, {"ts": "00:01:00", "text": "怎么样？", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:07", "text": "今天，是罚了学生吗？", "speaker": "老师", "tone": "询问", "sound": []}, {"ts": "00:01:15", "text": "罚了。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:22", "text": "身份转变成功。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:30", "text": "我激发了你。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:38", "text": "那我激发了乔老师，我也是个好老师，对不对？", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:45", "text": "那乔老师，要跟我说谢谢啊！", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:53", "text": "我说的是还有点怎么样。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:00", "text": "那你喜欢这种说法方式吗？", "speaker": "老师", "tone": "询问", "sound": []}, {"ts": "00:02:08", "text": "可是，我有点难过。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:16", "text": "因为小乔老师，忘记跟我说谢谢了。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:23", "text": "是在我提醒一下才说的。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:31", "text": "所以，小乔老师还要跟我说对不起，是不是？", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:38", "text": "小乔老师没有做一个有礼貌的表率啊！", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:46", "text": "所以，我们做老师的，其实最重要的是要给学生做表率，对不对？", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:54", "text": "那小乔老师，手伸出来。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:01", "text": "手掌向上，因为小乔老师犯了错，没有礼貌。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:09", "text": "所以我要给一些小小的惩罚。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:16", "text": "准备好了吗？", "speaker": "老师", "tone": "询问", "sound": []}, {"ts": "00:03:24", "text": "只有这样，小乔老师才能成为一个很优秀的老师。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:32", "text": "能够成为我们学校的骄傲。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:39", "text": "所以，我这也是没有办法的事情。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:47", "text": "手伸平。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:55", "text": "还好，没有叫也没有躲，都承受住了呢？", "speaker": "老师", "tone": "询问", "sound": []}, {"ts": "00:04:11", "text": "我看看。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:28", "text": "这双手一看就没干过什么活，细细腻腻的，都打红了？", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:45", "text": "好点了吗？", "speaker": "老师", "tone": "询问", "sound": []}, {"ts": "00:04:45", "text": "是第一次吧。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:45", "text": "放心吧，不会特别明显，可能你自己看不出来。", "speaker": "老师", "tone": "命令", "sound": []}, {"ts": "00:04:45", "text": "不过接下来的几天，", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:45", "text": "你每次抬手在黑板上写字的时候，", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:45", "text": "就可以看到手心上淡淡的惩罚的痕迹了。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:45", "text": "来提醒小乔老师，今天受到的惩罚。", "speaker": "老师", "tone": "责备", "sound": []}, {"ts": "00:04:45", "text": "所以，小乔老师以后，可以做个懂礼貌的好孩子。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:45", "text": "真可爱。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:45", "text": "好了，不早了，回去吧。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:45", "text": "以后还有任何教学上的问题，都可以再来找我。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:45", "text": "好吗？", "speaker": "老师", "tone": "询问", "sound": []}, {"ts": "00:04:45", "text": "走吧。", "speaker": "老师", "tone": "平静", "sound": []}], "scene": "资深前辈以老师身份对小乔老师进行礼仪娇育，因其未说谢谢、对不起而用手心受罚的方式惩戒，最后勉励其做懂礼貌的榜样。基调带角色扮演与管娇色彩。", "behaviors": [{"desc": "前辈指出小乔老师温柔易被学生欺负，义务指导"}, {"desc": "因小乔老师忘说谢谢、对不起，判定其失礼"}, {"desc": "令其伸手受罚，检查手心发红"}, {"desc": "收束，提醒其日后写字可见淡淡痕迹以自省，放其回去"}], "tone_summary": "（自动）老师视角独白，语气以平静、询问、责备为主，题材偏校园/师生。", "genre_tags": ["校园/师生"], "genre_main": "校园", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被老师倾诉/照顾/管教的一方（你）", "signature_elements": ["惩罚"], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "办公室的灯还亮着。齐老师批完最后一本作业，抬头看见门口站着个踌躇的身影，是他新来的同事，学生们口中温柔的乔老师。"}, {"type": "line", "speaker": "老师", "text": "晚安。你还没回去？"}, {"type": "narr", "text": "她走进来，犹豫着开口，说自己总被学生欺负，管不住纪律。齐老师合上教案，看了她一眼。"}, {"type": "line", "speaker": "老师", "text": "好。齐老师。怎么了？尽管问吧。像乔老师这么温柔，又是新面孔，被学生欺负也很正常。其实，我们做老师呢，对学生就是要严厉。"}, {"type": "line", "speaker": "老师", "text": "明天开始，要不这样，你过来。怎么样？"}, {"type": "narr", "text": "第二天，她按他说的做了——板起脸，罚了调皮的学生。下课后她来找他，有点心虚地汇报。他听完，嘴角浮起一点笑意。"}, {"type": "line", "speaker": "老师", "text": "今天，是罚了学生吗？罚了。身份转变成功。我激发了你。那我激发了乔老师，我也是个好老师，对不对？"}, {"type": "narr", "text": "她眨了眨眼，想了好一会儿才开口说了声谢谢。他却微微侧过头，语气里带着一点认真的失落。"}, {"type": "line", "speaker": "老师", "text": "那乔老师，要跟我说谢谢啊！我说的是还有点怎么样。那你喜欢这种说法方式吗？可是，我有点难过。因为小乔老师，忘记跟我说谢谢了。是在我提醒一下才说的。"}, {"type": "narr", "text": "她怔住了，没想到他会计较这个。他看着她，慢条斯理地补了一句。"}, {"type": "line", "speaker": "老师", "text": "所以，小乔老师还要跟我说对不起，是不是？小乔老师没有做一个有礼貌的表率啊！所以，我们做老师的，其实最重要的是要给学生做表率，对不对？"}, {"type": "narr", "text": "办公室里安静下来。他朝她伸出手，掌心向上，语气温和却带着不容拒绝的意味。"}, {"type": "line", "speaker": "老师", "text": "那小乔老师，手伸出来。手掌向上，因为小乔老师犯了错，没有礼貌。所以我要给一些小小的惩罚。准备好了吗？"}, {"type": "narr", "text": "她咬着唇，慢慢把手伸出去，摊平。他垂眼看着她细白的掌心，声音很轻，像是在讲一个道理。"}, {"type": "line", "speaker": "老师", "text": "只有这样，小乔老师才能成为一个很优秀的老师。能够成为我们学校的骄傲。所以，我这也是没有办法的事情。手伸平。"}, {"type": "narr", "text": "清脆的几声过后，他抬眼，看见她虽然红了眼眶，却始终没躲，也没喊疼。他顿了顿，指腹轻轻碰了碰她泛红的掌心。"}, {"type": "line", "speaker": "老师", "text": "还好，没有叫也没有躲，都承受住了呢？我看看。这双手一看就没干过什么活，细细腻腻的，都打红了？好点了吗？是第一次吧。放心吧，不会特别明显，可能你自己看不出来。"}, {"type": "narr", "text": "她低头看着自己的手心，听见他继续说下去，声音里竟带了一点不易察觉的温柔。"}, {"type": "line", "speaker": "老师", "text": "不过接下来的几天，你每次抬手在黑板上写字的时候，就可以看到手心上淡淡的惩罚的痕迹了。来提醒小乔老师，今天受到的惩罚。所以，小乔老师以后，可以做个懂礼貌的好孩子。真可爱。"}, {"type": "narr", "text": "夜风从窗缝里溜进来。他看了看表，收拾起桌上的教案，语气恢复如常。"}, {"type": "line", "speaker": "老师", "text": "好了，不早了，回去吧。以后还有任何教学上的问题，都可以再来找我。好吗？走吧。"}]}, {"no": 119, "id": "kjB-1aVrVRs", "title": "【Lの女性向音声】小乔老师 二", "title_zh": "小乔老师 二", "duration": "00:07:45", "link": "https://www.youtube.com/watch?v=kjB-1aVrVRs", "enriched": true, "lines": [{"ts": "00:00:00", "text": "来。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:02", "text": "我们准备上。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:04", "text": "小小老师。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:06", "text": "这件事。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:08-00:00:08", "text": "啊！", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:10", "text": "可是我的娇学进度的话。", "speaker": "老师", "tone": "宠溺", "sound": []}, {"ts": "00:00:12-00:00:45", "text": "（音频转写失真，已压缩）。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:47-00:00:52", "text": "嗯。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:55", "text": "好吧好吧？", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:57", "text": "行行好的。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:00", "text": "小小老师回来了。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:07", "text": "站我的课。", "speaker": "老师", "tone": "宠溺", "sound": []}, {"ts": "00:01:09", "text": "我倒没有生气。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:12", "text": "但是。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:15", "text": "我觉得你应该提前跟我说一声对吧？", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:18-00:01:32", "text": "嗯。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:34", "text": "不知道我知道我知道。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:37", "text": "小小老师压力也很大。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:39", "text": "可是。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:42", "text": "你不觉得这件事情。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:44", "text": "应该给我倒个钱吗？", "speaker": "老师", "tone": "询问", "sound": []}, {"ts": "00:01:47", "text": "就只是这样吗？", "speaker": "老师", "tone": "询问", "sound": []}, {"ts": "00:01:49", "text": "你看我今天在这么多学生面前。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:52", "text": "可是原来你的面走。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:54", "text": "所以。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:57-00:01:57", "text": "嗯。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:59", "text": "这太多很好。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:02", "text": "走吧。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:04", "text": "我们先去娇室。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:07", "text": "是不是还没有来过？", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:09", "text": "放学之后的娇室。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:12", "text": "因为今天的事情。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:15", "text": "是在娇室里发生的。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:18", "text": "所以我打算。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:20", "text": "在娇室里程发脾气。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:23", "text": "小小老师。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:26", "text": "站到讲台边上来。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:29", "text": "把鞋子头了。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:34", "text": "先带截开。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:40", "text": "骂仔也脱掉。", "speaker": "老师", "tone": "命令", "sound": []}, {"ts": "00:02:49", "text": "还羞吗？", "speaker": "老师", "tone": "询问", "sound": []}, {"ts": "00:02:53", "text": "你要知道。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:56", "text": "我做了这么多年老师。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:59", "text": "还是第一次有人赶强我的客。", "speaker": "老师", "tone": "宠溺", "sound": []}, {"ts": "00:03:02", "text": "所以。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:05", "text": "这样可能还不够。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:08", "text": "裙子提起来。", "speaker": "老师", "tone": "命令", "sound": []}, {"ts": "00:03:12", "text": "对。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:14", "text": "就这样。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:17", "text": "面对黑板。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:20", "text": "那会脱掉。", "speaker": "老师", "tone": "命令", "sound": []}, {"ts": "00:03:28", "text": "那会拉倒膝盖腿。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:35", "text": "放心吧过来的时候。", "speaker": "老师", "tone": "命令", "sound": []}, {"ts": "00:03:39", "text": "我已经把钱空关了。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:44", "text": "面对黑板。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:49", "text": "小小老师今天要站这里吧。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:51", "text": "在这里发展。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:54", "text": "这次是没有人的娇室。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:57", "text": "如果再有下次。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:59", "text": "可就在上课的时候。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:02", "text": "承发了。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:05", "text": "你想想那个场景。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:08", "text": "可能我还会问。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:10", "text": "同学们。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:13", "text": "知道讲台旁边这个人是谁吗？", "speaker": "老师", "tone": "询问", "sound": []}, {"ts": "00:04:16", "text": "没错。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:18", "text": "就是小小老师。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:21", "text": "那你们知道。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:24", "text": "小小老师为什么会被承发吗？", "speaker": "老师", "tone": "询问", "sound": []}, {"ts": "00:04:27", "text": "因为没礼貌。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:29", "text": "不对。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:32", "text": "上次被打过手心之后。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:35", "text": "他就改正了。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:38", "text": "因为强刻。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:42", "text": "也不对。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:46", "text": "因为小小老师。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:49", "text": "作为一个老师。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:52", "text": "在自己平时上课的娇室里。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:55", "text": "先提裙子。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:58", "text": "露出团部。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:01", "text": "不但没有回感。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:04", "text": "去了身体反应。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:07", "text": "大家看小小老师的大腿间。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:11", "text": "是不是有些亮晶晶的？", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:15", "text": "小小老师。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:17", "text": "究竟是初秋的夜风。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:20", "text": "扶过团部。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:22", "text": "刚休吃。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:25", "text": "还是吃饺才在娇室的地板上。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:27", "text": "不能逃跑。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:30", "text": "刚休吃呢？", "speaker": "老师", "tone": "询问", "sound": []}, {"ts": "00:05:33-00:05:35", "text": "可以了。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:37", "text": "可以放进来了。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:39", "text": "抱一下。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:41", "text": "抱抱。", "speaker": "老师", "tone": "撒娇", "sound": []}, {"ts": "00:05:44", "text": "做得很好。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:46", "text": "对。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:49", "text": "这怕结束了。", "speaker": "老师", "tone": "温柔", "sound": []}, {"ts": "00:05:52", "text": "坐这。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:56", "text": "想他有什么不能做的。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:06:00", "text": "帮你把娃娃的传上。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:06:07", "text": "脚底都菜糟了。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:06:16", "text": "怎么？", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:06:26", "text": "刚才都不害羞。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:06:36", "text": "现在害羞了。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:06:47", "text": "好了。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:06:50", "text": "咱那库就自己穿上吧。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:06:53", "text": "不需要泡芒了吧。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:06:56", "text": "等一下。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:07:00", "text": "帮你擦一下。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:07:03", "text": "不然穿上会失路路的。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:07:06", "text": "很难受的。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:07:10", "text": "口袋金是真丝的。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:07:13", "text": "我也会轻轻的不会痛的。", "speaker": "老师", "tone": "温柔", "sound": []}, {"ts": "00:07:17-00:07:31", "text": "好了。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:07:31", "text": "给穿上了。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:07:31", "text": "我倒是不心气。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:07:31", "text": "但是怕你会害羞。", "speaker": "老师", "tone": "温柔", "sound": []}, {"ts": "00:07:31", "text": "所以。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:07:31", "text": "帮我洗干净之后。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:07:31", "text": "再还给我。", "speaker": "老师", "tone": "命令", "sound": []}, {"ts": "00:07:31", "text": "好吗？", "speaker": "老师", "tone": "询问", "sound": []}], "scene": "前辈因小乔老师未提前请假而对其在空娇室进行管娇式惩戒，过程中带角色扮演与亲密互动，结束后为其整理、叮嘱归还衣物。含角色扮演与管娇情节、亲密互动。", "behaviors": [{"desc": "前辈表示未生气，但要求提前告知"}, {"desc": "带到放学后的娇室，令其站讲台边受罚"}, {"desc": "在空娇室进行管娇，并以下次当众相警示"}, {"desc": "结束惩戒，拥抱安抚"}, {"desc": "为其擦净、穿衣，叮嘱洗干净后归还"}], "tone_summary": "（自动）老师视角独白，语气以平静、询问、命令为主，题材偏校园/师生。", "genre_tags": ["校园/师生", "治愈"], "genre_main": "校园", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被老师倾诉/照顾/管教的一方（你）", "signature_elements": [], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "放学铃响过很久，办公室的门被轻轻敲响。齐老师抬头，看见小乔老师站在门口，神情有些局促。她今天擅自调了课，他等了整整一天，总算把人等来了。"}, {"type": "line", "speaker": "老师", "text": "来。我们准备上。小小老师。这件事。啊！可是我的娇学进度的话。嗯。好吧好吧？行行好的。小小老师回来了。站我的课。我倒没有生气。但是。我觉得你应该提前跟我说一声对吧？嗯。不知道我知道我知道。小小老师压力也很大。可是。你不觉得这件事情。应该给我倒个钱吗？"}, {"type": "narr", "text": "她低头认错，声音越来越小。他放下手里的教案，看着她，语气不重，却带着一点老师特有的威严。"}, {"type": "line", "speaker": "老师", "text": "就只是这样吗？你看我今天在这么多学生面前。可是原来你的面走。所以。嗯。这太多很好。走吧。我们先去娇室。是不是还没有来过？放学之后的娇室。因为今天的事情。是在娇室里发生的。所以我打算。在娇室里程发脾气。"}, {"type": "narr", "text": "她跟在他身后走进空无一人的教室。暮色从窗外渗进来，黑板上的粉笔字还留着今天的痕迹。他走到讲台边，回头看她，目光平静。"}, {"type": "line", "speaker": "老师", "text": "小小老师。站到讲台边上来。把鞋子头了。先带截开。骂仔也脱掉。还羞吗？你要知道。我做了这么多年老师。还是第一次有人赶强我的客。所以。这样可能还不够。裙子提起来。对。就这样。面对黑板。那会脱掉。那会拉倒膝盖腿。"}, {"type": "narr", "text": "她怔怔地站着，没有动，只是脸一寸一寸红起来。他看着她，没有催促，也没有退让，只是平静地继续说下去。"}, {"type": "line", "speaker": "老师", "text": "放心吧过来的时候。我已经把钱空关了。面对黑板。小小老师今天要站这里吧。在这里发展。这次是没有人的娇室。如果再有下次。可就在上课的时候。承发了。你想想那个场景。可能我还会问。同学们。知道讲台旁边这个人是谁吗？没错。就是小小老师。"}, {"type": "line", "speaker": "老师", "text": "那你们知道。小小老师为什么会被承发吗？因为没礼貌。不对。上次被打过手心之后。他就改正了。因为强刻。也不对。因为小小老师。作为一个老师。在自己平时上课的娇室里。先提裙子。露出团部。不但没有回感。去了身体反应。"}, {"type": "narr", "text": "他顿了顿，目光落在她身上，声音平得像在陈述一个事实。她的脸已经红透了，指尖攥着裙摆，指节泛白。"}, {"type": "line", "speaker": "老师", "text": "大家看小小老师的大腿间。是不是有些亮晶晶的？小小老师。究竟是初秋的夜风。扶过团部。刚休吃。还是吃饺才在娇室的地板上。不能逃跑。刚休吃呢？"}, {"type": "narr", "text": "教室里安静得能听见彼此的呼吸。他看了她很久，忽然走近一步，声音里那点严厉悄然退去，取而代之的是一丝说不清的温柔。"}, {"type": "line", "speaker": "老师", "text": "可以了。可以放进来了。抱一下。抱抱。做得很好。对。这怕结束了。坐这。想他有什么不能做的。帮你把娃娃的传上。脚底都菜糟了。怎么？刚才都不害羞。现在害羞了。好了。咱那库就自己穿上吧。不需要泡芒了吧。"}, {"type": "narr", "text": "她红着脸低头整理衣裙。他转过身，从抽屉里拿出一方叠得整整齐齐的手帕，是上次她落在这里的。他递给她，声音里带着一点笑意。"}, {"type": "line", "speaker": "老师", "text": "等一下。帮你擦一下。不然穿上会失路路的。很难受的。口袋金是真丝的。我也会轻轻的不会痛的。好了。给穿上了。我倒是不心气。但是怕你会害羞。所以。帮我洗干净之后。再还给我。好吗？"}]}, {"no": 120, "id": "a12M3DyO6MI", "title": "【Lの女性向音声】小乔老师 海边", "title_zh": "小乔老师 海边", "duration": "00:09:21", "link": "https://www.youtube.com/watch?v=a12M3DyO6MI", "enriched": true, "lines": [{"ts": "00:00:00", "text": "散步。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:12", "text": "到了。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:15", "text": "从这边走下去就是海了。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:19", "text": "没想到开这么久。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:22", "text": "我以为一个小时就能到呢？", "speaker": "老师", "tone": "询问", "sound": []}, {"ts": "00:00:26", "text": "路上真的有点赌。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:29", "text": "有先看看海吗？", "speaker": "老师", "tone": "询问", "sound": []}, {"ts": "00:00:33", "text": "那走吧，下车。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:37", "text": "拿着包。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:42", "text": "拿着。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:51", "text": "走吧。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:01-00:01:01", "text": "嗯。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:08", "text": "很漂亮是吧？", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:12", "text": "还好没有太晚。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:15", "text": "至少还有最后一次晚下奖礼我们。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:18", "text": "你看。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:21", "text": "鱼民应该都回家了吧。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:24", "text": "这个时候。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:27", "text": "我现在又正好是长潮。", "speaker": "老师", "tone": "责备", "sound": []}, {"ts": "00:01:31-00:01:31", "text": "嗯。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:34", "text": "两年没看过海。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:38", "text": "只有时候真的觉得。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:41", "text": "离开城市。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:44", "text": "再还偏走一走。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:48", "text": "而心里面觉得重要的人。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:51", "text": "是这样能挺太这一刻就好了。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:55-00:01:57", "text": "哦！", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:00", "text": "先先的。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:03", "text": "舒服。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:06", "text": "鞋子头掉。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:14", "text": "我帮你棉走一走。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:16", "text": "怎么样？", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:19-00:02:19", "text": "嗯。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:21", "text": "慢点慢点。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:24", "text": "等着我。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:27-00:02:27", "text": "嗯。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:35", "text": "有点凉。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:37", "text": "当然凉了。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:40", "text": "先都秋天了。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:43", "text": "是用一下就好了。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:48", "text": "小强老师。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:52", "text": "要不要试试个舒服的。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:57", "text": "那哭。", "speaker": "老师", "tone": "温柔", "sound": []}, {"ts": "00:03:02", "text": "多掉。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:07", "text": "装在包里就好。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:10", "text": "这样的话。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:13", "text": "风可以从轻子关进去。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:16", "text": "也特别舒服。", "speaker": "老师", "tone": "命令", "sound": []}, {"ts": "00:03:19", "text": "走了一天车。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:22", "text": "车一车。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:25", "text": "不能包包里啊！", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:29", "text": "回开休吗？", "speaker": "老师", "tone": "询问", "sound": []}, {"ts": "00:03:33", "text": "对我也回开休啊！", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:38", "text": "放心吧。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:41", "text": "这里确实没什么人。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:44", "text": "走吧。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:47", "text": "继续往前。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:50", "text": "今天小强老师。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:54", "text": "也没有做一个有礼貌的好孩子。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:59", "text": "今天有开车的时候。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:01", "text": "是天这么久。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:04", "text": "有累。", "speaker": "老师", "tone": "温柔", "sound": []}, {"ts": "00:04:07", "text": "小强老师捐把耳机戴上。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:09", "text": "自己在那儿听音乐。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:12-00:04:15", "text": "我变成你的司机了。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:20-00:04:20", "text": "嗯。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:24", "text": "只是对不起就可以吗？", "speaker": "老师", "tone": "询问", "sound": []}, {"ts": "00:04:29", "text": "那要怎么办。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:32", "text": "我觉得。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:35", "text": "如果不给小强老师一点惩罚的话。", "speaker": "老师", "tone": "责备", "sound": []}, {"ts": "00:04:38", "text": "小强老师作为老师一身作责。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:41", "text": "可能没有什么说服力。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:44", "text": "你说是吗？", "speaker": "老师", "tone": "询问", "sound": []}, {"ts": "00:04:47", "text": "就在这边吧。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:51", "text": "不在这个娇室上。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:56", "text": "手扶上面就好。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:02", "text": "然后会帮你把勤资见到要上。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:12", "text": "小强老师要人主。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:15", "text": "只是惩罚。", "speaker": "老师", "tone": "责备", "sound": []}, {"ts": "00:05:19", "text": "匹匹正对着大海。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:24", "text": "感觉很像一次对自然的会规。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:32", "text": "或者是对大海的至今。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:41", "text": "是不是？", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:50", "text": "小李。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:53", "text": "时间差不多了。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:56", "text": "开始。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:59", "text": "看到了没。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:06:03", "text": "那个是我专门。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:06:08", "text": "让人提前过来。", "speaker": "老师", "tone": "命令", "sound": []}, {"ts": "00:06:13", "text": "给你准备的。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:06:19", "text": "专心。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:06:50", "text": "好了。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:06:56", "text": "匹匹上的颜色。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:07:00", "text": "好像叶伙。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:07:05", "text": "待会儿那一个。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:07:08", "text": "放弃隐患的地方。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:07:11", "text": "就说没有住的地方。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:07:14", "text": "军队放下来了。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:07:20", "text": "会喜欢吗？", "speaker": "老师", "tone": "询问", "sound": []}, {"ts": "00:07:26", "text": "如果不害怕的话。", "speaker": "老师", "tone": "温柔", "sound": []}, {"ts": "00:07:30", "text": "全部。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:07:35", "text": "都掉。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:07:41", "text": "可以吗？", "speaker": "老师", "tone": "询问", "sound": []}, {"ts": "00:07:47", "text": "好。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:07:53", "text": "老师要你。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:07:56", "text": "叶伙大海。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:07:59", "text": "把手掌开。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:08:02", "text": "闭上眼睛。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:08:13", "text": "你没有觉得。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:08:18", "text": "还得到海里。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:08:23", "text": "因为我们出生的时候就是这样。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:08:29", "text": "你干嘛？", "speaker": "老师", "tone": "撒娇", "sound": []}, {"ts": "00:08:36", "text": "往里面走吧。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:08:39", "text": "可以往里面走一走。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:08:42", "text": "现在是长朝。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:08:45", "text": "即便是掉到海里。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:08:48", "text": "又会帮你退回来的。", "speaker": "老师", "tone": "责备", "sound": []}, {"ts": "00:08:51-00:08:54", "text": "别跑。", "speaker": "老师", "tone": "命令", "sound": []}, {"ts": "00:08:58", "text": "好了吗？", "speaker": "老师", "tone": "询问", "sound": []}, {"ts": "00:09:04", "text": "我让你妹妹送给准备的大胖鞋。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:09:07", "text": "可以给你布一布。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:09:11", "text": "不布你屁股上的伤。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:09:15", "text": "就这样走回车里吧。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:09:20", "text": "走。", "speaker": "老师", "tone": "平静", "sound": []}], "scene": "二人在海边散步放松，前辈因小乔老师途中失礼而在海边对其进行管娇式惩戒，最后为其擦伤、准备返程。含角色扮演与管娇情节。", "behaviors": [{"desc": "二人到海边下车散步"}, {"desc": "脱鞋让对方踩沙滩，慢慢走"}, {"desc": "指其途中不礼貌，决定给予惩罚"}, {"desc": "令其面朝大海、扶物受罚"}, {"desc": "让其张开手掌、闭眼，融入自然情境"}, {"desc": "为其擦伤，准备走回车里"}], "tone_summary": "（自动）老师视角独白，语气以平静、询问、责备为主，题材偏校园/师生。", "genre_tags": ["校园/师生"], "genre_main": "校园", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被老师倾诉/照顾/管教的一方（你）", "signature_elements": ["惩罚"], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "车子在沿海公路上开了很久，终于拐进一条安静的岔路。他停好车，侧头看向副驾的人，语气带着一点纵容。"}, {"type": "line", "speaker": "老师", "text": "到了，散步去。从这边走下去就是海了。没想到开了这么久，路上还有点堵，我以为一个小时就能到呢？"}, {"type": "narr", "text": "她往窗外张望，远处是一片温柔的海平线。他先下了车，绕过来替她开门，接过她手里的包。"}, {"type": "line", "speaker": "老师", "text": "先看看海吗？那走吧，下车。包给我，拿着。走吧。"}, {"type": "narr", "text": "两个人沿着沙路往海边走，潮声越来越近。他在前面停下，回头看她，眼底映着最后一缕晚霞。"}, {"type": "line", "speaker": "老师", "text": "很漂亮吧？还好没有太晚，至少还赶得上最后一次晚霞。你看，渔民应该都回家了吧，这个点，又正好是涨潮。"}, {"type": "narr", "text": "她站在他身边，望着辽阔的海面，一时没有说话。海风把她的头发吹起来，他伸手，替她把乱发别到耳后。"}, {"type": "line", "speaker": "老师", "text": "两年没看过海了。有时候真的觉得，离开城市，在海边走一走，心里面觉得重要的人，也是这样能停在这一刻就好了。"}, {"type": "narr", "text": "她微微红了眼眶，没有接话。他也没追问，只是拉着她继续往前走。"}, {"type": "line", "speaker": "老师", "text": "先先的，舒服。鞋子脱掉吧，我帮你拿着，走一走怎么样？"}, {"type": "narr", "text": "她听话地脱了鞋，光脚踩上微凉的细沙。他牵着她，慢慢往水边走。"}, {"type": "line", "speaker": "老师", "text": "慢点慢点，等着我。嗯，有点凉吧？当然凉了，都秋天了。适应一下就好了。"}, {"type": "narr", "text": "海水漫过脚背，又缓缓退去。她笑了一下，像是很久没有这么放松过。他站在她身后，目光却忽然带上了别的意味。"}, {"type": "line", "speaker": "老师", "text": "小乔老师，要不要试试个舒服的？那哭什么，多掉，装在包里就好。这样的话，风可以从裙子灌进去，也特别舒服。"}, {"type": "narr", "text": "她脸一红，下意识捂住裙摆。他低笑，语气却带着不容商量的意思。"}, {"type": "line", "speaker": "老师", "text": "走了一天车，累了吧？不能装在包里吗？回去还要开很久，对，我也要开很久，放心吧，这里确实没什么人。走吧，继续往前。"}, {"type": "narr", "text": "她抿了抿唇，没有反驳。两个人沿着海滩继续走，潮声里只剩下脚踩沙地的声响。"}, {"type": "line", "speaker": "老师", "text": "今天小乔老师，可没有做一个有礼貌的好孩子呢。今天开车的时候，等这么久，有点累。小乔老师把耳机戴上，自己在那儿听音乐——我变成你的司机了。"}, {"type": "narr", "text": "她脚步一顿，心虚地低下头，小声说了句对不起。他停下来，转过身，语气带着玩味。"}, {"type": "line", "speaker": "老师", "text": "只是对不起就可以吗？那要怎么办？我觉得，如果不给小乔老师一点惩罚的话，小乔老师作为老师，以身作则，可能没有什么说服力。你说是吗？"}, {"type": "narr", "text": "她僵在原地，心跳一点点加快。他没有给她太多反应的时间，指了指旁边一块礁石。"}, {"type": "line", "speaker": "老师", "text": "就在这边吧。不在这个礁石上，手扶上面就好。然后我会帮你把裙子卷到腰上。"}, {"type": "narr", "text": "她咬着唇，犹豫了一瞬，还是慢慢走过去，双手扶住礁石。他走到她身后，声音低下来。"}, {"type": "line", "speaker": "老师", "text": "小乔老师要记住，这只是惩罚。屁屁正对着大海，感觉很像一次对自然的献礼，或者是对大海的致敬。是不是？"}, {"type": "narr", "text": "潮声在耳边起伏，她闭了闭眼，耳根烧得通红。他抬起手，语气却放轻了些。"}, {"type": "line", "speaker": "老师", "text": "时间差不多了，开始。"}, {"type": "narr", "text": "巴掌落下来的时候，她整个人一颤，咬着唇没有出声。他没有留情，一下一下，隔着薄薄的布料。"}, {"type": "line", "speaker": "老师", "text": "看到了没？那个，是我专门让人提前过来给你准备的。专心点。"}, {"type": "narr", "text": "她顺着他的目光看去，远处的礁石上放着一双崭新的拖鞋。她怔了一下，还没回过神，又挨了一下。"}, {"type": "line", "speaker": "老师", "text": "好了。屁屁上的颜色，好像也红透了。待会儿那一个，放心，没有住的地方，军队放下来了。会喜欢吗？"}, {"type": "narr", "text": "她带着哭腔嗯了一声。他这才放过她，替她把裙子整理好，声音温和下来。"}, {"type": "line", "speaker": "老师", "text": "如果不害怕的话，全部都脱掉，可以吗？好。老师要你，也爱上大海。把手张开，闭上眼睛。"}, {"type": "narr", "text": "她照做，张开手臂，闭上眼睛。海风灌满衣摆，潮声温柔。他站在她身后，声音带着笑意。"}, {"type": "line", "speaker": "老师", "text": "你没有觉得，就像回到海里吗？因为我们出生的时候，就是这样。你干嘛？往里面走吧，可以往里面走一走。现在是涨潮，即便是掉到海里，浪又会帮你退回来的。别跑。"}, {"type": "narr", "text": "她睁开眼，笑着往海里跑了几步，又被浪花追回来。他在岸边看着她，眼底满是纵容的光。"}, {"type": "line", "speaker": "老师", "text": "好了吗？我让人给你准备的大拖鞋，可以给你敷一敷，敷你屁股上的伤。就这样走回车里吧，走。"}, {"type": "narr", "text": "她穿上那双大拖鞋，跟在他身后往回走。海风把两个人的影子拉得很长，身后是渐渐暗下去的海面。那一顿罚、一场浪，和一双专门为她准备的拖鞋——他说得对，这片海，她大概也会爱上很久。"}]}, {"no": 121, "id": "Cec4PQjJ-jI", "title": "【Lの女性向音声】小朋友不承认错误，屁屁是要开花的", "title_zh": "小朋友不承认错误，屁屁是要开花的", "duration": "00:06:38", "link": "https://www.youtube.com/watch?v=Cec4PQjJ-jI", "enriched": true, "lines": [{"ts": "00:00:00", "text": "别过来，通通不许过来！", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:00:03", "text": "好好好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:06", "text": "我不碰，不碰。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:09-00:00:12", "text": "睡吧。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:16", "text": "主人在。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:19", "text": "再忍忍。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:22-00:00:28", "text": "我承认这一刻——", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:32", "text": "我确实有些内疚。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:35", "text": "摸着她微微发烫的身体和红通通的屁股，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:38", "text": "听着她用沙哑的声音，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:41", "text": "和几乎一模一样的话质问我，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:44", "text": "为什么不相信她？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:48", "text": "我突然清醒。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:51", "text": "也许这并不只是她的错。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:54", "text": "而是我在主观里，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:57", "text": "想当然的认为，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:01", "text": "只可能是她错了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:04", "text": "她只是个小姑娘。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:07", "text": "做不好？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:10", "text": "或者做错了，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:13", "text": "告诉她，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:17", "text": "哄哄她不就好了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:20", "text": "又何必下如此重手呢？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:01:23", "text": "我究竟想让她承认什么呢？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:01:26", "text": "我想我大概是疯了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:29", "text": "看到她柔弱的样子，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:33", "text": "和乞求的眼神，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:36", "text": "我只想用近乎疯狂的举动，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:39", "text": "惩罚的，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:42", "text": "折磨的。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:46", "text": "跪了这么久，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:49", "text": "发现她怎么样了？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:52", "text": "嘴不说话是什么意思？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:55", "text": "是不知道哪错了，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:58", "text": "而是不认为自己错了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:01", "text": "摇头。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:04", "text": "摇头。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:08", "text": "看样子是要和我硬扛到底了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:11", "text": "好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:14", "text": "好的。", "speaker": "主人", "tone": "宠溺", "sound": []}, {"ts": "00:02:17", "text": "那就看看是我的戒尺硬，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:20", "text": "还是你的嘴硬。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:02:23", "text": "过来。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:02:26", "text": "我要你过来。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:30", "text": "脚踝上绑好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:34", "text": "腿伸直。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:38", "text": "小东西。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:43", "text": "我再给你一次机会。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:47", "text": "如果不行，让你的屁股替你受罪。", "speaker": "主人", "tone": "撒娇", "sound": []}, {"ts": "00:02:51", "text": "你最好乖乖认错。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:56", "text": "还是不说话是吧？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:00", "text": "行。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:04", "text": "那我们去拿藤条来抽。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:09", "text": "手抓住脚踝。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:03:13", "text": "不许躲。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:03:17", "text": "也不许挡。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:22", "text": "也不用报数。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:26", "text": "如果你想通了，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:30", "text": "就大声地说，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:35", "text": "主人我错了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:39", "text": "听懂了？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:44", "text": "现在开始。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:48", "text": "今天这么能忍的。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:52", "text": "小东西。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:03:56", "text": "你的小屁股都肿起来了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:00-00:04:03", "text": "还不大声说点什么？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:06", "text": "你没错？", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:04:10", "text": "那我们换藤条。", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:04:13", "text": "趴好。", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:04:17", "text": "玩你怕一下。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:20", "text": "躲什么？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:04:24", "text": "嘴不挺硬的吗？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:26", "text": "你没有拒绝的权力。", "speaker": "主人", "tone": "撒娇", "sound": []}, {"ts": "00:04:29", "text": "你乖乖认错，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:32", "text": "我可以考虑换个工具。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:35", "text": "不认？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:38", "text": "好。", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:04:41", "text": "趴好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:44-00:04:50", "text": "我们继续。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:56", "text": "手拿开。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:05:02", "text": "不许挡。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:04", "text": "小心。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:06", "text": "你没有睡到头。", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:05:08-00:05:10", "text": "我没事。", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:05:13", "text": "没事。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:15", "text": "主人在呢？", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:05:17", "text": "哭吧。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:19-00:05:21", "text": "想坏了是不是？", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:05:24", "text": "多疼。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:30", "text": "你也一直是吓死我了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:33", "text": "突然就撑不住了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:36", "text": "所以你宁愿摔下来，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:40", "text": "也不肯跟主人认错。", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:05:43", "text": "藤条都抽断了，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:47", "text": "还是不肯认错。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:50", "text": "果然是个倔强的小丫头。", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:05:54", "text": "还能动吗？", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:05:57", "text": "有没有缓过来一点？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:01", "text": "慢点。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:06:04", "text": "慢起来。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:08", "text": "靠在怀里。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:12", "text": "哎哟。", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:06:16", "text": "我就哭这么凶。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:20", "text": "来擦擦眼泪。", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:06:24", "text": "眼睛都哭肿了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:29", "text": "主人没有不相信你。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:34", "text": "只是。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:34", "text": "我现在抱你去床上。", "speaker": "主人", "tone": "平静", "sound": []}], "scene": "主仆角色扮演中，小朋友不肯认错，主人以打臀方式惩戒，过程中自省下手过重，最终停手安抚、上药。含角色扮演与管娇情节。", "behaviors": [{"desc": "主人摸到对方发烫红肿的屁股，自省不该重手"}, {"desc": "令其跪久、伸直腿，给最后一次认错机会"}, {"desc": "开始打臀惩戒，对方仍不认错"}, {"desc": "换工具继续，对方仍硬扛"}, {"desc": "对方突然撑不住哭，主人停手安抚"}, {"desc": "抱其到床上，准备上药"}], "tone_summary": "（自动）主人视角独白，语气以平静、温柔、命令为主，题材偏古风。", "genre_tags": ["古风", "主仆/调教", "治愈"], "genre_main": "古风", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被主人倾诉/照顾/管教的一方（你）", "signature_elements": [], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "她把自己缩在角落里，红着眼睛，说什么都不肯过来。他放软了语气，慢慢蹲下身。"}, {"type": "line", "speaker": "主人", "text": "别过来，通通不许过来！好好好，我不碰，不碰。睡吧，主人在。再忍忍。"}, {"type": "narr", "text": "他承认，这一刻他确实有些内疚。摸着她微微发烫的身体和红通通的屁股，听着她用沙哑的声音，用几乎一模一样的话质问他：为什么不相信她？他突然清醒了。"}, {"type": "narr", "text": "也许这并不只是她的错，而是他在主观里想当然地认为，只可能是她错了。她只是个小姑娘，做不好，或者做错了，告诉她、哄哄她不就好了，又何必下如此重手呢？"}, {"type": "narr", "text": "他问自己：我究竟想让她承认什么呢？我想我大概是疯了。看到她柔弱的样子和乞求的眼神，我只想用近乎疯狂的举动去惩罚她、折磨她。"}, {"type": "line", "speaker": "主人", "text": "跪了这么久，发现她怎么样了？嘴不说话是什么意思？"}, {"type": "narr", "text": "她沉默着。那不是不知道错在哪，而是不认为自己错了。她摇头，再摇头，看样子是要和他硬扛到底了。"}, {"type": "line", "speaker": "主人", "text": "好，好的。那就看看是我的戒尺硬，还是你的嘴硬。"}, {"type": "line", "speaker": "主人", "text": "过来。我要你过来。脚踝上绑好，腿伸直，小东西。"}, {"type": "narr", "text": "他最后一次给她机会，声音沉下来。"}, {"type": "line", "speaker": "主人", "text": "我再给你一次机会。如果不行，让你的屁股替你受罪。你最好乖乖认错。"}, {"type": "narr", "text": "她还是不说话。他站起身，语气冷了下去。"}, {"type": "line", "speaker": "主人", "text": "还是不说话是吧？行。那我们去拿藤条来抽。"}, {"type": "line", "speaker": "主人", "text": "手抓住脚踝，不许躲，也不许挡，也不用报数。如果你想通了，就大声地说：主人我错了。听懂了？现在开始。"}, {"type": "narr", "text": "藤条落下，一下又一下。她却始终咬着嘴唇，一个字都不肯说。他看着那一片红肿，忽然有些心惊。"}, {"type": "line", "speaker": "主人", "text": "今天这么能忍的，小东西。你的小屁股都肿起来了，还不大声说点什么？"}, {"type": "narr", "text": "她终于撑不住，身体一歪，几乎从边上摔下来。他眼疾手快接住了她，心口狠狠一紧。"}, {"type": "line", "speaker": "主人", "text": "小心。你没有睡到头。我没事，没事，主人在呢？哭吧。"}, {"type": "narr", "text": "她哭得上气不接下气，他这才后怕起来——她宁愿摔下来，也不肯跟主人认错。藤条都抽断了，还是不肯认错，果然是个倔强的小丫头。"}, {"type": "line", "speaker": "主人", "text": "想坏了是不是？多疼。你也一直是吓死我了。突然就撑不住了。"}, {"type": "line", "speaker": "主人", "text": "所以你宁愿摔下来，也不肯跟主人认错。藤条都抽断了，还是不肯认错。果然是个倔强的小丫头。"}, {"type": "narr", "text": "他小心翼翼把她扶起来，让她靠进自己怀里，声音放得很轻很轻。"}, {"type": "line", "speaker": "主人", "text": "还能动吗？有没有缓过来一点？慢点，慢起来。靠在怀里。"}, {"type": "line", "speaker": "主人", "text": "哎哟，我就哭这么凶。来擦擦眼泪，眼睛都哭肿了。"}, {"type": "line", "speaker": "主人", "text": "主人没有不相信你。只是——我现在抱你去床上。"}, {"type": "narr", "text": "他把她抱起来，步子稳而缓，低头在她耳边轻声说着，语气里再没有半点冷硬，只剩心疼。"}]}, {"no": 122, "id": "ALPGwi_yDa8", "title": "【Lの女性向音声】小朋友当然要宠着啦", "title_zh": "小朋友当然要宠着啦", "duration": "00:06:12", "link": "https://www.youtube.com/watch?v=ALPGwi_yDa8", "enriched": true, "lines": [{"ts": "00:00:00", "text": "人牛奶都喝掉了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:02", "text": "真怪，高看你。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:04", "text": "过来吧，来海里。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:00:07", "text": "转过来坐腿上。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:00:09", "text": "对。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:11-00:00:14", "text": "这样就可以看起来。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:00:16-00:00:19", "text": "来，来，来。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:21", "text": "转过来坐腿上。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:00:23", "text": "对。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:26", "text": "转过来坐腿上。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:00:28", "text": "这样就可以看到。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:30", "text": "你开的下链带了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:33", "text": "让我一眼。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:35", "text": "不过你真的好帅。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:38", "text": "好甜啊！", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:40", "text": "好像咬一口。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:42", "text": "好好。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:45-00:00:47", "text": "好好抱着。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:50", "text": "怎么又把小脑袋埋起来了？", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:00:54", "text": "你这个样子。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:58", "text": "哎，这听话的像猫一模一样。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:01:03", "text": "然后给小猫。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:06", "text": "驴驴毛。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:10", "text": "就算怕着吧。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:01:13", "text": "不累。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:01:17", "text": "小香的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:23", "text": "抱抱。", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:01:25", "text": "我懂究竟最近好想点门门不乐的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:28", "text": "是不是？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:31", "text": "我怎么能看不出来呢？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:01:33", "text": "你这个小家伙。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:36", "text": "有时没睡又着个眉头。", "speaker": "哥哥", "tone": "责备", "sound": []}, {"ts": "00:01:39", "text": "明明笑起来那么好看。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:01:41", "text": "然后整天一点颜色的样子。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:44", "text": "很疼。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:01:47", "text": "哎，我太多看看。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:49", "text": "这多看看。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:52", "text": "有小嘴头就起来了。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:01:55", "text": "你看宝贝以前是一个喜欢。", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:01:57", "text": "想哥哥撒娇。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:00", "text": "每天都要抱抱。", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:02:03", "text": "年年的小姑娘。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:05", "text": "从什么时候开始。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:08", "text": "你好像。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:11", "text": "在哥哥面前。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:13", "text": "你也可以随时柔软一些。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:16", "text": "随时发生大哭。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:02:18", "text": "随时护脚蛮沉的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:21", "text": "这是哥哥给你一个人的权力。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:24", "text": "你这么懂事。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:26", "text": "让我特别心疼。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:02:29", "text": "你知道吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:02:32", "text": "有时候我甚至乖自己。", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:02:34", "text": "被保护好你感觉。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:37", "text": "觉得我没有那么喜心。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:40", "text": "会忽略你的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:42", "text": "忽略你的小情绪。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:45", "text": "看，还是这么乖。", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:02:47", "text": "那也能不能答应我。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:50", "text": "要是有委屈了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:53", "text": "一定要说出来。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:55", "text": "不去自己闻着。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:58", "text": "听到了吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:03:01", "text": "不要觉得说不出口。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:03", "text": "只要了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:06", "text": "有委屈又不开心了。", "speaker": "哥哥", "tone": "责备", "sound": []}, {"ts": "00:03:09", "text": "一定要勇敢地说出来。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:11", "text": "跟哥哥讲。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:14", "text": "跟哥哥讲是最安全的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:17", "text": "你要知道。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:20", "text": "哥哥只是想更爱你一些。", "speaker": "哥哥", "tone": "宠溺", "sound": []}, {"ts": "00:03:23", "text": "通过各种方式。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:26", "text": "好好爱你。", "speaker": "哥哥", "tone": "宠溺", "sound": []}, {"ts": "00:03:29", "text": "你当然可以做个小朋友了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:32", "text": "不对，你本来就是小朋友。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:35", "text": "在哥哥这里。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:38", "text": "你是我一个人的小朋友。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:42", "text": "现在还没去吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:03:44", "text": "那笑一下好不好？", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:03:46", "text": "是在对吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:03:48", "text": "你看，你也想。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:50", "text": "我也想了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:52", "text": "都好。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:54", "text": "你要不笑的话。", "speaker": "哥哥", "tone": "宠溺", "sound": []}, {"ts": "00:03:56", "text": "我的不敢笑。", "speaker": "哥哥", "tone": "宠溺", "sound": []}, {"ts": "00:03:58", "text": "是不是？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:01", "text": "那好了，报也报了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "我以后了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:05", "text": "现在。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:08", "text": "我有话要问你。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:10", "text": "最近又没有好好吃饭对吧？", "speaker": "哥哥", "tone": "责备", "sound": []}, {"ts": "00:04:13", "text": "这准备往哪儿躲啊！", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:15", "text": "别动。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:04:17", "text": "老师过待着。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:20", "text": "也不开心。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:22", "text": "就喜欢做这种对自己身体不好的事。", "speaker": "哥哥", "tone": "宠溺", "sound": []}, {"ts": "00:04:25", "text": "是不是？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:27", "text": "谁挂的你？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:30", "text": "你看看我们。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:32", "text": "我们家抽地力的药。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:34", "text": "自己为不好？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:36", "text": "自己不清楚。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:39", "text": "还有。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:41", "text": "这哪个小家伙上次饭地鞋堂。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:44", "text": "差点运过去。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:47", "text": "后来我跟你没见衣服里。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:50", "text": "都塞在她。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:53", "text": "怎么了？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:56", "text": "忘了吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:04:59", "text": "哥哥也不想凶你啊！", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:01", "text": "只是希望你要好好对自己。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:03", "text": "爱你。", "speaker": "哥哥", "tone": "宠溺", "sound": []}, {"ts": "00:05:05", "text": "从来都不是。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:07", "text": "纵容你犯错的理由。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:09", "text": "这点你要明白。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:11", "text": "哎呦呦呦。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:13", "text": "哎呀！", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:05:15", "text": "不哭不哭不哭。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:05:17", "text": "抱着抱着抱着。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:19", "text": "抱着你还另回去。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:21", "text": "哎呦刚刚我时间了吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:05:25", "text": "我知道宝贝最乖了。", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:05:28", "text": "没错。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:32", "text": "其实你不乖一点。", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:05:35", "text": "也可以。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:39", "text": "但是超过自己这件事情。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:42", "text": "一定要乖乖听话。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:05:46", "text": "再亲一下。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:49-00:05:53", "text": "不高。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:57", "text": "两个不高。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:07", "text": "爱你这件事。", "speaker": "哥哥", "tone": "宠溺", "sound": []}, {"ts": "00:06:07", "text": "是我做过最正确的事。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:07", "text": "现在了。", "speaker": "哥哥", "tone": "平静", "sound": []}], "scene": "哥哥把小朋友抱坐腿上宠溺安抚，察觉其近来闷闷不乐，鼓励其有委屈要说出来，并叮嘱好好吃饭、爱自己。基调宠溺温柔。", "behaviors": [{"desc": "哥哥让小朋友坐腿上，夸其可爱"}, {"desc": "察觉其近来不乐，心疼其懂事"}, {"desc": "给其可随时柔软、撒娇的特权，鼓励说出委屈"}, {"desc": "重申在哥哥这里永远可以做小朋友"}, {"desc": "检查其不好好吃饭、叮咛爱自己"}, {"desc": "以爱你是最正确的事收束"}], "tone_summary": "（自动）哥哥视角独白，语气以平静、命令、撒娇为主，题材偏古风。", "genre_tags": ["古风", "校园/师生", "治愈"], "genre_main": "古风", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被哥哥倾诉/照顾/管教的一方（你）", "signature_elements": [], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "客厅的沙发上，他把最后一盒牛奶递给她，看着她咕咚咕咚喝完，眼底带着满意的笑。"}, {"type": "line", "speaker": "哥哥", "text": "人牛奶都喝掉了。真乖，高看你。过来吧，来怀里。转过来坐腿上。对，这样就可以看到。来，来，来。转过来坐腿上。对。这样就可以看到，你刚才戴的那条项链了。让我看一眼。不过，你真的好帅。好甜啊！好像咬一口。好好，好好抱着。"}, {"type": "narr", "text": "她窝在他腿上，被他圈在怀里，小声说哥哥别闹。他低头看着她，忽然轻轻叹了口气，伸手揉了揉她的小脑袋。"}, {"type": "line", "speaker": "哥哥", "text": "怎么又把小脑袋埋起来了？你这个样子，哎，这听话得像猫一模一样。然后给小猫撸撸毛，就算怕着吧。不累，小香的。抱抱。我懂，你最近好想点闷闷不乐的，是不是？我怎么能看不出来呢？你这个小家伙。"}, {"type": "narr", "text": "她在他怀里没有说话，只是把脸埋得更深。他一下一下顺着她的背，声音温柔得像在哄一个真正的小孩子。"}, {"type": "line", "speaker": "哥哥", "text": "有时没睡着，又皱着个眉头。明明笑起来那么好看，然后整天一点颜色的样子。很疼？哎，我多看看，这多看看，有小嘴头就起来了。你看，宝贝以前是一个喜欢跟哥哥撒娇，每天都要抱抱、黏黏的小姑娘。从什么时候开始，你好像——在哥哥面前，你也可以随时柔软一些，随时大哭，随时胡搅蛮缠。"}, {"type": "narr", "text": "他顿了顿，声音低下去，带着认真的郑重。"}, {"type": "line", "speaker": "哥哥", "text": "这是哥哥给你一个人的权力。你这么懂事，让我特别心疼，你知道吗？有时候我甚至怪自己，没有保护好你，觉得我没有那么细心，会忽略你的小情绪。看，还是这么乖。那你能不能答应我，要是有委屈了，一定要说出来，不要自己闷着。听到了吗？不要觉得说不出口。只要有委屈，又不开心了，一定要勇敢地说出来，跟哥哥讲。跟哥哥讲，是最安全的。"}, {"type": "narr", "text": "她在他怀里，终于轻轻应了一声。他低头看着她，语气带着一点满足的笑意。"}, {"type": "line", "speaker": "哥哥", "text": "你要知道，哥哥只是想更爱你一些，通过各种方式，好好爱你。你当然可以做个小朋友。不对，你本来就是小朋友。在哥哥这里，你是我一个人的小朋友。现在还没去吗？那笑一下好不好？是在对吗？你看，你也想，我也想了。都好。你要不笑的话，我都不敢笑。是不是？"}, {"type": "narr", "text": "她终于弯起嘴角，露出一个浅浅的笑。他看着她，也跟着笑起来，语气却忽然一转，带着一点审问的意味。"}, {"type": "line", "speaker": "哥哥", "text": "那好了，抱也抱了，笑也笑了。现在，我有话要问你。最近又没有好好吃饭，对吧？这准备往哪儿躲啊！别动，老实待着。又不开心，就喜欢做这种对自己身体不好的事，是不是？谁教你的？你看看我们，我们家抽屉里的药，自己不知道？自己不清楚？"}, {"type": "narr", "text": "她低下头，心虚地绞着手指。他叹了口气，语气带着心疼的责备。"}, {"type": "line", "speaker": "哥哥", "text": "还有，这哪个小家伙上次在饭堂，差点晕过去。后来我跟你没见衣服里，都塞着糖。怎么了？忘了吗？哥哥也不想凶你啊！只是希望你要好好对自己。爱你，从来都不是纵容你犯错的理由。这点你要明白。"}, {"type": "narr", "text": "她眼眶一下子就红了，眼泪啪嗒啪嗒往下掉。他慌了，连忙把人搂进怀里，一下一下拍着她的背。"}, {"type": "line", "speaker": "哥哥", "text": "哎呦呦呦，哎呀！不哭不哭不哭，抱着抱着抱着。抱着你，还跟你回去。哎呦，刚刚我凶你了吗？我知道宝贝最乖了。没错。其实你不乖一点，也可以。但是伤害自己这件事情，一定要乖乖听话。再亲一下。不高？两个不高。爱你这件事，是我做过最正确的事。"}, {"type": "narr", "text": "她在他怀里，抽噎着慢慢停下来，小声说，哥哥，对不起。他低头，在她额角落下一个吻，声音温柔得不像话。"}, {"type": "line", "speaker": "哥哥", "text": "傻孩子，说什么对不起。以后每一顿，都要好好吃饭。哥哥会看着你的。嗯，现在就带你去吃点好吃的？不哭了，抱抱就出发。"}, {"type": "narr", "text": "窗外的夕阳正好。她被他牵着手走出门，眼睛还红红的，嘴角却翘了起来。她知道的——在哥哥这里，她可以永远做一个被宠着的小朋友。而好好吃饭这件事，从今天起，会有人一直替她记着。"}]}, {"no": 123, "id": "mCLBYpn0LvQ", "title": "【Lの女性向音声】小王子 一", "title_zh": "小王子 一", "duration": "00:02:56", "link": "https://www.youtube.com/watch?v=mCLBYpn0LvQ", "enriched": true, "lines": [{"ts": "00:00:00", "text": "当我还只有六岁的时候，在一本描写原始森林的名叫《真实的故事》的书中，看到一幅精彩的插画，画的是一条蟒蛇正在吞一只大野兽。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "那头上就是那幅画的摹本。这本书中写道：蟒蛇把他们的猎物不加咀嚼地囫囵吞下，然后他们就再也不能动弹了，他们就这样在长长的六个月的睡眠中消化这些食物。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "当时我对丛林中的奇遇想得很多，于是我用彩色铅笔画出了我的第一幅图画，我的第一号作品。它是这样的。", "speaker": "大人", "tone": "宠溺", "sound": []}, {"ts": "00:00:00", "text": "我把这幅画拿给大人看，我问他们：我的画是不是叫他们害怕？他们回答我：一顶帽子有什么可怕的？", "speaker": "大人", "tone": "温柔", "sound": []}, {"ts": "00:00:00", "text": "我画的不是帽子，是一条巨蟒在消化一头大象。于是我又把巨蟒肚子的情况画了出来，让大人能够看懂。大人们总是需要解释。我的第二号作品是这样的。", "speaker": "大人", "tone": "责备", "sound": []}, {"ts": "00:00:00", "text": "大人们把这些画着开了肚皮或闭上肚皮的蟒蛇的图画放到一边，还是把兴趣放在地理、历史、算术和语法上。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "就这样，在六岁那年，我就放弃了当画家这一美好的职业。我的第一号、第二号作品的不成功，让我泄了气。大人们靠他们自己什么也不懂，还得老是不断地给他们做解释。", "speaker": "大人", "tone": "宠溺", "sound": []}, {"ts": "00:00:00", "text": "这真叫孩子们泄气。后来我只好选择另一个职业，我学会了开飞机，世界各地差不多都飞到过。地理学帮了我很大的忙，我一眼就能分辨出中国和亚里桑那，要是夜里迷失了航向，这是很有用的。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "这样，在我的生活中，我跟许多严肃的人有过很多接触。我在大人们中间生活过很长时间，我自己观察过他们。", "speaker": "大人", "tone": "宠溺", "sound": []}, {"ts": "00:00:00", "text": "但这并没有使我对他们的看法有多大改变。当我遇到一个头脑看起来稍微清楚的大人时，我就拿出一直保存着的我的第一号作品来测试他。", "speaker": "大人", "tone": "命令", "sound": []}, {"ts": "00:00:00", "text": "我想知道他是否真的有理解力。可是得到的回答却是：这是顶帽子。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "我就不谈蟒蛇、原始森林或者星星之类的事儿了。我迁就他们的水平，和他们谈一些桥牌、高尔夫球、政治和领带啊这些。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "于是大人们就十分高兴，认识了这样一个通情达理的人。", "speaker": "大人", "tone": "平静", "sound": []}], "scene": "朗读《小王子》节选（一）：叙述者六岁画吞象的蟒蛇被大人误认为帽子，从而放弃画家梦想、改学飞行，并学会以大人能理解的方式交谈。纯文学朗读。", "behaviors": [{"desc": "朗读六岁作画与大人误读帽子的情节"}, {"desc": "叙述放弃画家职业、学飞行、周游世界"}, {"desc": "以测试大人理解力、顺应其话题收束"}], "tone_summary": "（自动）大人视角独白，语气以平静、宠溺、温柔为主，题材偏校园/师生。", "genre_tags": ["校园/师生"], "genre_main": "校园", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被大人倾诉/照顾/管教的一方（你）", "signature_elements": ["绑"], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "台灯的光落在书页上，他的声音平静而舒缓，像是在讲一个很远的故事。他翻开第一页，慢慢念起来。"}, {"type": "line", "speaker": "大人", "text": "当我还只有六岁的时候，在一本描写原始森林的名叫《真实的故事》的书中，看到一幅精彩的插画，画的是一条蟒蛇正在吞一只大野兽。那头上就是那幅画的摹本。这本书中写道：蟒蛇把他们的猎物不加咀嚼地囫囵吞下，然后他们就再也不能动弹了，他们就这样在长长的六个月的睡眠中消化这些食物。"}, {"type": "narr", "text": "他停了一下，声音里带着一点回忆般的笑意，继续念下去。"}, {"type": "line", "speaker": "大人", "text": "当时我对丛林中的奇遇想得很多，于是我用彩色铅笔画出了我的第一幅图画，我的第一号作品。它是这样的。我把这幅画拿给大人看，我问他们：我的画是不是叫他们害怕？他们回答我：一顶帽子有什么可怕的？我画的不是帽子，是一条巨蟒在消化一头大象。于是我又把巨蟒肚子的情况画了出来，让大人能够看懂。大人们总是需要解释。我的第二号作品是这样的。"}, {"type": "narr", "text": "他念到这里，轻轻顿了顿，像是也想起了自己小时候那些不被理解的画。"}, {"type": "line", "speaker": "大人", "text": "大人们把这些画着开了肚皮或闭上肚皮的蟒蛇的图画放到一边，还是把兴趣放在地理、历史、算术和语法上。就这样，在六岁那年，我就放弃了当画家这一美好的职业。我的第一号、第二号作品的不成功，让我泄了气。大人们靠他们自己什么也不懂，还得老是不断地给他们做解释。这真叫孩子们泄气。后来我只好选择另一个职业，我学会了开飞机，世界各地差不多都飞到过。"}, {"type": "narr", "text": "他翻过一页，声音低下去，带着故事特有的温度。"}, {"type": "line", "speaker": "大人", "text": "这样，在我的生活中，我跟许多严肃的人有过很多接触。我在大人们中间生活过很长时间，我自己观察过他们。但这并没有使我对他们的看法有多大改变。当我遇到一个头脑看起来稍微清楚的大人时，我就拿出一直保存着的我的第一号作品来测试他。我想知道他是否真的有理解力。可是得到的回答却是：这是顶帽子。"}, {"type": "narr", "text": "他合上书页前，轻轻念完最后一段，声音里带着一点无奈又释然的笑意。"}, {"type": "line", "speaker": "大人", "text": "我就不谈蟒蛇、原始森林或者星星之类的事儿了。我迁就他们的水平，和他们谈一些桥牌、高尔夫球、政治和领带啊这些。于是大人们就十分高兴，认识了这样一个通情达理的人。"}, {"type": "narr", "text": "夜很静，他把书合上，指尖停在封面上。那些关于蟒蛇和星星的故事，也许只有孩子才懂。而大人，早已忘了怎么抬头看星星。"}]}, {"no": 124, "id": "Zx96BrlWjDY", "title": "【Lの女性向音声】小王子 七", "title_zh": "小王子 七", "duration": "00:05:55", "link": "https://www.youtube.com/watch?v=Zx96BrlWjDY", "enriched": true, "lines": [{"ts": "00:00:00", "text": "第五天，还是羊的事儿，把小王子的生活秘密一向我解开了。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:00:03", "text": "好像默默地思索了很长时间以后，得出了什么结果都一样。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:00:06", "text": "他突然没头脑地问我，羊要是吃小关幕，他也要吃花了。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:00:10", "text": "他碰到什么吃什么？", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:00:13", "text": "连有刺的话也吃吗？", "speaker": "先生", "tone": "询问", "sound": []}, {"ts": "00:00:17", "text": "有刺的也吃。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:00:20", "text": "那刺有什么用呢？", "speaker": "先生", "tone": "询问", "sound": []}, {"ts": "00:00:23", "text": "我不知道该怎么回答。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:00:27", "text": "那或着忙着要从发动机场，卸下一个宁的太近的螺丝。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:00:30", "text": "我发现机器鼓掌似乎很严重，因此也快完了。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:00:34", "text": "我担心可能会发生最坏的情况，心里挺着急的。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:00:37", "text": "那刺有什么用呢？", "speaker": "先生", "tone": "询问", "sound": []}, {"ts": "00:00:40", "text": "小王子一旦提出了问题，从来他都不会放过。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:00:44", "text": "他这那个盖子的螺丝真的很脑火。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:00:47", "text": "于是我就随便回答他一句。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:00:51", "text": "刺马什么用都没有，这纯粹是划得恶劣表现。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:00:54", "text": "可知道陈默黎一会儿。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:00:57", "text": "我这不满的心情从我说。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:01:01", "text": "我不信，划是弱小的，纯粗的。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:01:04", "text": "他总是在想方事发保护自己。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:01:08", "text": "以为有了刺就可以显出自己很厉害的样子。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:01:11", "text": "我没不做生。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:01:14", "text": "我当时想。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:01:18", "text": "如果这个螺丝再和我左对，我就云一锤子瞧掉他。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:01:21", "text": "小王子又来打扰我的思绪了。", "speaker": "先生", "tone": "责备", "sound": []}, {"ts": "00:01:25", "text": "可是你确认为话。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:01:28", "text": "算了吧，算了吧，我什么也不认为。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:01:31", "text": "我是随便回答你的。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:01:35", "text": "我现在看到我有正经事要做。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:01:38", "text": "他今晚的看着我说。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:01:42", "text": "正经事儿。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:01:45", "text": "他丑助我手拿锤子手指沾满了油屋。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:01:49", "text": "扶在一个他看来。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:01:52", "text": "丑不可严的机前上。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:01:55", "text": "你说话就和那些大人一样。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:01:59", "text": "这个话是我点难看了。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:02:02", "text": "可是他又坚可无情地说的。", "speaker": "先生", "tone": "责备", "sound": []}, {"ts": "00:02:06", "text": "你什么都分不清。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:02:09", "text": "你把什么都混在一起。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:02:12", "text": "他丑是非常浪货。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:02:16", "text": "搅动着脑袋。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:02:19", "text": "金黄的头发。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:02:23", "text": "随风产动着。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:02:26", "text": "我倒过一个星球。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:02:29", "text": "上面住过一个红脸先生。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:02:33", "text": "他从来没闻过一朵花。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:02:36", "text": "他从来没看过一颗星星。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:02:40", "text": "他什么人也没有喜欢过。", "speaker": "先生", "tone": "宠溺", "sound": []}, {"ts": "00:02:43", "text": "除了算这样以外。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:02:46", "text": "他什么也没有做过。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:02:50", "text": "他整天都你一样老是说。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:02:53", "text": "我有正经事儿。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:02:57", "text": "我是个严肃的人。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:03:00", "text": "这是他奥气是足。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:03:03", "text": "他简直不像个人。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:03:07", "text": "他是个魔固。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:03:10", "text": "他是个什么？", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:03:14", "text": "是个魔固。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:03:17", "text": "小样子当时气得脸色发白。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:03:21", "text": "几百万年以来。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:03:23", "text": "花儿都在制造这词。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:03:26", "text": "几百万年以来。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:03:29", "text": "洋人要吃花儿。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:03:32", "text": "要搞清楚为什么花儿。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:03:35", "text": "非这么大劲给自己制造。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:03:38", "text": "没有用的词。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:03:41", "text": "这难道不是正经事儿。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:03:44", "text": "难道洋和花之前的战争不重要。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:03:47", "text": "这难道不比那个大胖子红脸先生的账目更重要。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:03:50", "text": "如果我认识一朵人事件唯一的话。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:03:53", "text": "只有我的心就有它。", "speaker": "先生", "tone": "宠溺", "sound": []}, {"ts": "00:03:56", "text": "围的地方不存在。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:03:59", "text": "而这小样忽历糊涂地就把他一下子毁掉了。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:04:02", "text": "这难道不重要。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:04:05", "text": "他气得脸发红。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:04:08", "text": "然后又说着。", "speaker": "先生", "tone": "责备", "sound": []}, {"ts": "00:04:10", "text": "如果有人爱上了在这一万科星星中独一无二的一朵花。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:04:13", "text": "但他看着这些星星的时候。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:04:16", "text": "这就足以使他感到幸福。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:04:19", "text": "他可以自言自语地说。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:04:22", "text": "我的内朵花儿就在其中的一个星星上。", "speaker": "先生", "tone": "宠溺", "sound": []}, {"ts": "00:04:25", "text": "但如果洋吃掉那朵花儿。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:04:28", "text": "对他来说。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:04:31", "text": "好像所有的星星。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:04:34", "text": "一下子全都熄灭了一样。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:04:37", "text": "这难道也不重要吗？", "speaker": "先生", "tone": "询问", "sound": []}, {"ts": "00:04:40", "text": "他无法再说下去了。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:04:43", "text": "突然气不成声。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:04:46", "text": "也没尽强力。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:04:49", "text": "我放下手中的工具。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:04:52", "text": "我把吹则。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:04:55", "text": "落定。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:04:58", "text": "即刻。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:05:00", "text": "死亡。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:05:03", "text": "全部跑出脑后。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:05:06", "text": "在一个星球上。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:05:09", "text": "在我的星星上。", "speaker": "先生", "tone": "宠溺", "sound": []}, {"ts": "00:05:12", "text": "在地球上。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:05:15", "text": "有一个小王子需要安眉。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:05:18", "text": "我把他抱在怀里。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:05:21", "text": "我摇着他。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:05:24", "text": "对他说。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:05:27", "text": "你爱的那朵花儿没有威胁。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:05:30", "text": "我给你的小养化了一个照子。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:05:33", "text": "我给你的花花了一副亏家。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:05:36", "text": "我也不太知道该说些什么？", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:05:39", "text": "我觉得自己有点本着。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:05:42", "text": "我不知道怎样才能达到他的境界。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:05:45", "text": "怎样才能再进入他的境界。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:05:48", "text": "泪水世界。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:05:48", "text": "是多么神秘的。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:05:48", "text": "晚安。", "speaker": "先生", "tone": "平静", "sound": []}, {"ts": "00:05:48", "text": "宝贝。", "speaker": "先生", "tone": "撒娇", "sound": []}], "scene": "朗读《小王子》节选（七）：小王子追问刺的用处，叙述者忙于修飞机而敷衍，二人就正经事争论花与羊孰重，最终叙述者安抚哭泣的小王子。纯文学朗读。", "behaviors": [{"desc": "朗读第五天小王子问羊是否吃花、刺有何用"}, {"desc": "叙述者修飞机分心，敷衍回答引发小王子不满"}, {"desc": "小王子动情论述花与星空的珍贵，气到哽咽"}, {"desc": "叙述者抱慰小王子，以晚安宝贝收束"}], "tone_summary": "（自动）先生视角独白，语气以平静、询问、宠溺为主，题材偏现代情侣。", "genre_tags": ["现代情侣"], "genre_main": "现代情侣", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被先生倾诉/照顾/管教的一方（你）", "signature_elements": [], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "第五天，还是关于羊的事，把小王子生活的秘密向我解开了一角。他好像默默思索了很长时间以后，得出了什么结论似的，突然没头没脑地问我：羊要是吃灌木，它也要吃花了吗？"}, {"type": "line", "speaker": "小王子", "text": "羊要是吃灌木，它也要吃花了。他碰到什么吃什么？"}, {"type": "line", "speaker": "小王子", "text": "连有刺的花也吃吗？"}, {"type": "narr", "text": "我说，有刺的也吃。"}, {"type": "line", "speaker": "小王子", "text": "那刺有什么用呢？"}, {"type": "narr", "text": "我不知道该怎么回答。当时我正忙着从发动机上卸下一个拧得太紧的螺丝。我发现机器故障似乎很严重，心里挺着急，担心会发生最坏的情况。"}, {"type": "line", "speaker": "小王子", "text": "那刺有什么用呢？"}, {"type": "narr", "text": "小王子一旦提出问题，就从来不会放过。我正为那个盖子的螺丝恼火，于是随便回答了他一句：刺什么用都没有，这纯粹是花儿的恶劣表现。"}, {"type": "narr", "text": "他沉默了一会儿，不满的心情从脸上流露出来，对我说：我不信。花是弱小的、纯真的，她总是在想方设法保护自己，以为有了刺就可以显出自己很厉害的样子。"}, {"type": "narr", "text": "我没有作声。我当时想：如果这个螺丝再和我作对，我就一锤子敲掉它。偏偏小王子又来打扰我的思绪了。"}, {"type": "line", "speaker": "小王子", "text": "可是你，却认为花——"}, {"type": "narr", "text": "我说：算了吧，算了吧，我什么也不认为，我是随便回答你的，我现在有正经事要做。他惊讶地看着我。"}, {"type": "line", "speaker": "小王子", "text": "正经事儿！"}, {"type": "narr", "text": "他看见我手拿锤子、手指沾满了油污，伏在一个在他看来丑不可言的机器上。"}, {"type": "line", "speaker": "小王子", "text": "你说话就和那些大人一样。"}, {"type": "narr", "text": "这话让我有点难堪，可他又毫不留情地说下去。"}, {"type": "line", "speaker": "小王子", "text": "你什么都分不清，你把什么都混在一起。"}, {"type": "narr", "text": "他非常愤怒，晃动着脑袋，金黄的头发随风飘动。"}, {"type": "line", "speaker": "小王子", "text": "我到过一个星球，上面住着一个红脸先生。他从来没闻过一朵花，从来没看过一颗星星，什么人也没有喜欢过。除了算账以外，他什么也没有做过。他整天都像你一样，老是说：我有正经事儿，我是个严肃的人。"}, {"type": "line", "speaker": "小王子", "text": "他傲气十足，简直不像个人，他是个蘑菇。"}, {"type": "narr", "text": "他是个什么？我问。是个蘑菇！小王子当时气得脸色发白。"}, {"type": "line", "speaker": "小王子", "text": "几百万年以来，花儿都在制造刺。几百万年以来，羊儿都在吃花。要搞清楚为什么花儿非要费这么大劲，给自己制造没有用的刺，这难道不是正经事儿？难道羊和花之间的战争不重要？这难道不比那个大胖子红脸先生的账目更重要？"}, {"type": "line", "speaker": "小王子", "text": "如果我认识一朵人世间独一无二的花，只有我的星球上有它，别的地方都不存在，而这朵花被一只羊稀里糊涂地一下子毁掉了，这难道不重要？"}, {"type": "narr", "text": "他气得脸发红，然后又说着。"}, {"type": "line", "speaker": "小王子", "text": "如果有人爱上了在这亿万颗星星中独一无二的一朵花，当他看着这些星星的时候，这就足以使他感到幸福。他可以自言自语地说：我的那朵花儿就在其中的一个星星上。"}, {"type": "line", "speaker": "小王子", "text": "但如果羊吃掉那朵花儿，对他来说，好像所有的星星一下子全都熄灭了一样。这难道也不重要吗？"}, {"type": "narr", "text": "他无法再说下去了，突然泣不成声。夜已降临，我放下手中的工具。什么锤子、螺丝钉、口渴、死亡，全都抛到脑后。在一个星球上，在我的星星上，在地球上，有一个小王子需要安慰。"}, {"type": "narr", "text": "我把他抱在怀里，摇着他，对他说：你爱的那朵花儿没有危险，我给你的小羊画了一个罩子，我给你的花画了一副盔甲。"}, {"type": "narr", "text": "我也不知道该说些什么，觉得自己有点笨拙。我不知道怎样才能达到他的境界，怎样才能再进入他的境界。泪水世界，是多么神秘的。晚安，宝贝。"}]}, {"no": 125, "id": "ZrQzOeia6LQ", "title": "【Lの女性向音声】小王子 三", "title_zh": "小王子 三", "duration": "00:03:05", "link": "https://www.youtube.com/watch?v=ZrQzOeia6LQ", "enriched": true, "lines": [{"ts": "00:00:00", "text": "我花了很长时间才弄清楚他是从哪里来的。小王子向我提出了很多问题。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "可是对我提出的问题，他好像压根没听见似的。他无意中透露了一些话，逐渐让我搞清了他的来历。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "例如他第一次看见我的飞机时，他问我：这是个什么东西？这不是什么东西，它能飞。这是飞机，是我的飞机。", "speaker": "他", "tone": "宠溺", "sound": []}, {"ts": "00:00:00", "text": "我当时很骄傲地告诉他我能飞。于是他惊讶地说道：怎么，你是从天上掉下来的？是的。我谦虚地作了回答，这真滑稽。当时小王子发出一阵清脆的笑声，这使我很不高兴。", "speaker": "他", "tone": "宠溺", "sound": []}, {"ts": "00:00:00", "text": "我要求别人严肃对待我的不幸。然后他又说道：那么你也是从天上来的？你是哪个星球上的？", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:00:00", "text": "即刻，对于他是从哪里来的这个秘密，我隐约发现了一点线索，于是我突然问道：你是从另一个星球上来的吗？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:00:00", "text": "可是他不回答我的问题。他一面看着我的飞机，一面微微点点头，继续说道：可不是吗，", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:00:00", "text": "乘坐这玩意儿，你不可能是从很远的地方来的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "说到这里，他就长时间地陷入了沉思。然后从口袋里掏出绣花的小羊，看着他的宝贝，入了神。", "speaker": "他", "tone": "撒娇", "sound": []}, {"ts": "00:00:00", "text": "你们可以想见，这种关于别的星球的若明若暗的话语，让我心里多么好奇，因此我极力想知道其中更多的奥秘。", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:00:00", "text": "你是从哪儿来的，小家伙？你住在什么地方？你要把我的小羊带到哪儿去？", "speaker": "他", "tone": "宠溺", "sound": []}, {"ts": "00:00:00", "text": "他沉思了一会儿，然后回答我说：幸好你们给了我一个箱子，夜晚可以给我的小羊当房子用。", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:00:00", "text": "嗯，那当然。如果你听话的话，我再给你一根绳子，白天还可以拴住它，再加上一根杆子。", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:00:00", "text": "我的建议看来使小王子有点反感：拴住它，多奇怪的主意。如果你不拴住它，它就会到处跑，会跑丢的。我的这位朋友又笑出了声。", "speaker": "他", "tone": "责备", "sound": []}, {"ts": "00:00:00", "text": "你想要它跑到哪儿去呀？", "speaker": "他", "tone": "撒娇", "sound": []}, {"ts": "00:00:00", "text": "不管什么地方，它一直往前跑。这是小王子郑重其事地说。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "嗯，这没什么关系，我那里很小很小。接着他略带伤感地补充了一句：", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "一直往前走，也走不出多远。", "speaker": "他", "tone": "命令", "sound": []}], "scene": "朗读《小王子》节选（三）：叙述者弄清小王子来自外星，二人聊飞机、星球与小王子珍爱的小羊，并讨论用绳子拴住小羊。纯文学朗读。", "behaviors": [{"desc": "朗读小王子初见飞机、问其来历"}, {"desc": "追问小王子来自哪颗星球，引出小羊"}, {"desc": "讨论给小羊罩子与拴绳，小王子略带伤感收束"}], "tone_summary": "（自动）他视角独白，语气以平静、命令、宠溺为主，题材偏现代情侣。", "genre_tags": ["现代情侣"], "genre_main": "现代情侣", "emotion_arc": "（自动）平静→命令", "intensity": "中偏高", "listener_role": "（自动）被他倾诉/照顾/管教的一方（你）", "signature_elements": [], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "我花了很长时间才弄清楚小王子是从哪里来的。他向我提出很多问题，对我问的话却像没听见。他无意间说出的几句话，渐渐让我摸清了他的来历。"}, {"type": "line", "speaker": "他", "text": "这是个什么东西？"}, {"type": "narr", "text": "他第一次看见我的飞机时这样问。我告诉他，这不是什么东西，它能飞，这是飞机，是我的飞机。我很骄傲地告诉他我能飞。"}, {"type": "line", "speaker": "他", "text": "怎么，你是从天上掉下来的？"}, {"type": "narr", "text": "我谦虚地回答了，这真滑稽。小王子发出一阵清脆的笑声，让我有些不高兴——我正希望别人严肃地对待我的不幸。"}, {"type": "line", "speaker": "他", "text": "那么你也是从天上来的？你是哪个星球上的？"}, {"type": "narr", "text": "这句话让我隐约发现了一点关于他来历的线索。我追问他是不是从另一个星球来的，他却只顾看着我的飞机，微微点头。"}, {"type": "line", "speaker": "他", "text": "可不是吗，乘坐这玩意儿，你不可能是从很远的地方来的。"}, {"type": "narr", "text": "说完，他就长时间地陷入了沉思，随后从口袋里掏出那幅画着箱子的小羊的画，看着他的宝贝，入了神。这种若明若暗的话让我心里充满好奇，我极力想知道其中的奥秘。"}, {"type": "line", "speaker": "他", "text": "你是从哪儿来的，小家伙？你住在什么地方？你要把我的小羊带到哪儿去？"}, {"type": "narr", "text": "他沉思了一会儿才回答：幸好你们给了我一个箱子，夜晚可以给我的小羊当房子用。"}, {"type": "line", "speaker": "他", "text": "嗯，那当然。如果你听话的话，我再给你一根绳子，白天还可以拴住它，再加上一根杆子。"}, {"type": "narr", "text": "这个建议显然让小王子有些反感。"}, {"type": "line", "speaker": "他", "text": "拴住它，多奇怪的主意。"}, {"type": "narr", "text": "我告诉他，如果不拴住它，它就会到处跑，会跑丢的。我的这位朋友又笑出了声。"}, {"type": "line", "speaker": "他", "text": "你想要它跑到哪儿去呀？"}, {"type": "line", "speaker": "他", "text": "不管什么地方，它一直往前跑。嗯，这没什么关系，我那里很小很小。"}, {"type": "narr", "text": "接着，他略带伤感地补充了一句："}, {"type": "line", "speaker": "他", "text": "一直往前走，也走不出多远。"}]}, {"no": 126, "id": "vDmdg5uEtds", "title": "【Lの女性向音声】小王子 九", "title_zh": "小王子 九", "duration": "00:03:37", "link": "https://www.youtube.com/watch?v=vDmdg5uEtds", "enriched": true, "lines": [{"ts": "00:00:00", "text": "我想小王子大概是利用一群野鸟迁徙的机会跑出来的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "就在他出发的那天早上，他把他的星球收拾得整整齐齐。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "把他上头的活火山打扫得干干净净。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "他有两个活火山，早上热早点很方便。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "他还有一座死火山，他也把它打扫得干干净净。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "他想：说不定，它还会活动呢？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:00:00", "text": "打扫干净了，他们就可以慢慢地有规律地燃烧，而不会突然爆发。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "火山爆发就像烟囱里的火焰一样。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "当然，在我们地球上，我们人太小，不能打扫火山。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "可是火山给我们带来很多很多的麻烦。", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:00:00", "text": "小王子还把剩下的最后几棵猴面包树苗全拔了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "他有点忧伤，他以为他再也不会回来了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "这天，这些家常活使他感到特别的亲切。", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:00:00", "text": "当他最后一次浇花时，准备把它好好珍藏起来，", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:00:00", "text": "他发觉自己要哭出来了。", "speaker": "他", "tone": "温柔", "sound": []}, {"ts": "00:00:00", "text": "再见了，他对花儿说到。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "可是花儿没有回答他。再见了，他又说了一遍。", "speaker": "他", "tone": "责备", "sound": []}, {"ts": "00:00:00", "text": "花儿咳嗽了一声，但并不是因为感冒，他终于对他说到：", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "我一直很蠢，请你原谅我吧，希望你能幸福。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "花儿对他毫不抱怨，他感到很惊讶。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "他举着玻璃罩子，不知该说什么才好。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "他不明白她为什么会这样的温柔恬静。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "的确，我爱你，花儿对他说到，但又因我的过错，你一点也没有理会。", "speaker": "他", "tone": "责备", "sound": []}, {"ts": "00:00:00", "text": "这已经不重要了。不过你也和我一样的蠢。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "希望你今后能够幸福。把罩子放在一边吧，我用不着了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "那要是风来了怎么办？", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "我的感冒并不那么重，夜晚的凉风对我倒有好处。我是一朵花儿。", "speaker": "他", "tone": "宠溺", "sound": []}, {"ts": "00:00:00", "text": "那要是有虫子和野兽呢？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:00:00", "text": "要是想认识蝴蝶，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "经不起两三只虫子是不行的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "据说，这是很美的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:00", "text": "不然，还有谁来看我呢？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:00:00", "text": "你就要到远方去了。至于说大动物，我并不怕，我有爪子。", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:00:00", "text": "于是，她天真地显露出那四根刺，最后又说到：别这么磨蹭了，真烦人！", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:00:00", "text": "你既然决定离开这儿，那就快走吧。", "speaker": "他", "tone": "责备", "sound": []}, {"ts": "00:00:00", "text": "她是怕小王子看见她在哭。她是一朵非常骄傲的花儿。", "speaker": "他", "tone": "温柔", "sound": []}, {"ts": "00:00:00", "text": "晚安。", "speaker": "他", "tone": "平静", "sound": []}], "scene": "朗读类（文学有声书）。配音者以旁白/小王子视角讲述小王子离开自己星球的过程：打扫火山、拔除最后的猴面包树幼苗，并与那朵骄傲的花儿告别。花儿在告别时吐露爱意并鼓励他远行，小王子带着忧伤离去。基调温柔伤感，主题为离别、成长与表面骄傲下的温情。无亲密或惩罚情节。", "behaviors": [{"desc": "小王子收拾星球、打扫两座火山，为离开做准备"}, {"desc": "小王子拔掉最后的猴面包树幼苗，带着不会再回来的忧伤告别"}, {"desc": "花儿向小王子道歉并表达爱意，说他与自己同样纯洁"}, {"desc": "花儿强忍眼泪催他快走，小王子离去；旁白以晚安收尾"}], "tone_summary": "（自动）他视角独白，语气以平静、命令、询问为主，题材偏现代情侣。", "genre_tags": ["现代情侣"], "genre_main": "现代情侣", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被他倾诉/照顾/管教的一方（你）", "signature_elements": [], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "我想，小王子大概是趁着一群野鸟迁徙的机会跑出来的。就在出发的那天早上，他把星球收拾得整整齐齐，把两座活火山打扫得干干净净——早上热早点很方便。那座死火山他也打扫了，想着说不定它还会活动呢。打扫干净了，它们就能慢慢地、有规律地燃烧，而不会突然爆发。"}, {"type": "narr", "text": "小王子还把剩下的最后几棵猴面包树苗全拔了。他有点忧伤，以为再也不会回来了。这天，这些家常活让他感到特别亲切。当他最后一次浇花，准备把它好好珍藏起来时，他发觉自己要哭出来了。"}, {"type": "line", "speaker": "他", "text": "再见了。"}, {"type": "narr", "text": "他对花儿说。可是花儿没有回答。他又说了一遍再见。花儿咳嗽了一声——并不是因为感冒。她终于开口了："}, {"type": "line", "speaker": "他", "text": "我一直很蠢，请你原谅我吧，希望你能幸福。"}, {"type": "narr", "text": "花儿对他毫不抱怨，他感到很惊讶。他举着玻璃罩子，不知该说什么才好，不明白她为什么这样温柔恬静。"}, {"type": "line", "speaker": "他", "text": "的确，我爱你。但因为我自己的过错，你一点也没有理会。这已经不重要了，不过你也和我一样蠢。希望你今后能够幸福。把罩子放在一边吧，我用不着了。"}, {"type": "line", "speaker": "他", "text": "那要是风来了怎么办？"}, {"type": "line", "speaker": "他", "text": "我的感冒并不那么重，夜晚的凉风对我倒有好处。我是一朵花儿。"}, {"type": "line", "speaker": "他", "text": "那要是有虫子和野兽呢？"}, {"type": "line", "speaker": "他", "text": "要是想认识蝴蝶，经不起两三只虫子是不行的。据说，这是很美的。不然，还有谁来看我呢？你就要到远方去了。至于大动物，我并不怕，我有爪子。"}, {"type": "narr", "text": "她天真地显露出那四根刺，最后又说道："}, {"type": "line", "speaker": "他", "text": "别这么磨蹭了，真烦人！你既然决定离开这儿，那就快走吧。"}, {"type": "narr", "text": "她是怕小王子看见她在哭。她是一朵非常骄傲的花儿。晚安。"}]}, {"no": 127, "id": "TOZaSCFLLvk", "title": "【Lの女性向音声】小王子 二", "title_zh": "小王子 二", "duration": "00:05:26", "link": "https://www.youtube.com/watch?v=TOZaSCFLLvk", "enriched": true, "lines": [{"ts": "00:00:00", "text": "我就这样孤独的生活著。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:03", "text": "没有一个能真正谈得来的人。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:06", "text": "一直到六年前。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:09", "text": "在三哈拉沙漠上发生那次事故。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:12", "text": "我的发动机里有个东西损坏了。", "speaker": "大人", "tone": "宠溺", "sound": []}, {"ts": "00:00:15", "text": "但是由于我既没有带机械师也没有带旅客。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:19", "text": "我就试图独自完成这个困难的维修工作。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:22", "text": "这对我来说。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:25", "text": "是个生育似的问题。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:28", "text": "我随身带的水。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:31", "text": "只够引用一个星期。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:34", "text": "第一天晚上我就睡在这远离人间烟火的大沙漠上。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:38", "text": "我比大海中附在小模牌上的云南车。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:41", "text": "还要孤独很多。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:44", "text": "而第二天附小。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:47", "text": "当你一个奇怪的小声音叫醒我是。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:50", "text": "你们可以想见我当时多么痴疾。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:54", "text": "这个小小的声音说到。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:00:57", "text": "请你给我画一只山羊好吗？", "speaker": "大人", "tone": "询问", "sound": []}, {"ts": "00:01:00", "text": "给我画一只羊。", "speaker": "大人", "tone": "命令", "sound": []}, {"ts": "00:01:03", "text": "我像是受到了精雷的红鸡把一下子就站了起来。", "speaker": "大人", "tone": "命令", "sound": []}, {"ts": "00:01:06", "text": "我实际的揉了揉眼睛仔细地看了看。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:09", "text": "我看见一个十分奇怪的小家伙。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:13", "text": "严肃的吵我。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:16", "text": "宁魔望着。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:19", "text": "这是后来我给他画出来的。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:22", "text": "最好的一幅画像。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:25", "text": "可是我的话当然要比他本人的模样迅速很多。", "speaker": "大人", "tone": "宠溺", "sound": []}, {"ts": "00:01:29", "text": "这不是我的过头。", "speaker": "大人", "tone": "宠溺", "sound": []}, {"ts": "00:01:32", "text": "六岁的时候。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:35", "text": "大人们是我对华家的生涯失去了勇气。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:38", "text": "除了画过开著肚皮和闭著肚皮的帽蛇。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:41", "text": "后来再没有学过画。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:44", "text": "我经济的正大的眼前看着这突然出现的小家伙。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:48", "text": "你们不要忘记我当时是处在远离人间千里之外的地方。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:51", "text": "而是个小家伙给我的印象是。", "speaker": "大人", "tone": "命令", "sound": []}, {"ts": "00:01:54", "text": "他记不像米勒路的样子。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:01:57", "text": "也没有半点的疲乏。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:00", "text": "鸡可惧怕的深情。", "speaker": "大人", "tone": "温柔", "sound": []}, {"ts": "00:02:04", "text": "他似乎。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:06", "text": "他似乎不像是一个迷失在大沙漠中的孩子。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:09", "text": "当我在惊讶之中。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:12", "text": "中又能说出话来的时候对他说。", "speaker": "大人", "tone": "责备", "sound": []}, {"ts": "00:02:15", "text": "你在这儿干什么？", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:18", "text": "可是他却不宽不忙的好像有一件重要的事情一般对我重复说的。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:21", "text": "前给我画一只山羊。", "speaker": "大人", "tone": "命令", "sound": []}, {"ts": "00:02:24", "text": "当一种神秘的东西把你震出的时候。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:27", "text": "你是不敢不听从他的职配的。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:30", "text": "在这个狂物人员的沙漠上。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:33", "text": "面临死亡的危险的情况下。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:35", "text": "尽管这样的举动让我觉得十分荒诞。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:38", "text": "但我还是掏出了职和笔。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:41", "text": "这是我有机器。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:44", "text": "我只学过弟弟历史。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:47", "text": "算数。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:50", "text": "与法。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:53", "text": "九点不太开心的对小家伙说我不会画画。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:56", "text": "但回答我说。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:02:59", "text": "没有关系。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:02", "text": "跟画一只羊吧。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:04", "text": "因为我从来没有画过羊。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:07", "text": "我就给他。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:10", "text": "从我仅仅会画的两幅画堂中。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:13", "text": "那幅。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:16", "text": "闭著肚皮的俱盲。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:19", "text": "不不要忙著。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:22", "text": "他肚子里还有一头像。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:25", "text": "我听了他的话简直木灯口袋。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:28", "text": "他接著说。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:31", "text": "俱盲这东西太危险了。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:33", "text": "大象。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:36", "text": "又太占地方。", "speaker": "大人", "tone": "责备", "sound": []}, {"ts": "00:03:39", "text": "我住的地方非常小。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:42", "text": "我需要一只羊。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:45", "text": "都要画一只羊吧。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:48", "text": "于是我就给他画了。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:51", "text": "他专心地看着最后又说。", "speaker": "大人", "tone": "责备", "sound": []}, {"ts": "00:03:54", "text": "我不要。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:03:57", "text": "这只羊已经病得很重了给我重新画一只。", "speaker": "大人", "tone": "命令", "sound": []}, {"ts": "00:04:00", "text": "我又画了起来。", "speaker": "大人", "tone": "命令", "sound": []}, {"ts": "00:04:03", "text": "我的这位朋友天真可爱的笑了。", "speaker": "大人", "tone": "宠溺", "sound": []}, {"ts": "00:04:03", "text": "并且客气的拒绝到。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "你看。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "你画的不是小羊是头宫羊还有鸡奖呢？", "speaker": "大人", "tone": "询问", "sound": []}, {"ts": "00:04:03", "text": "于是我又重新画了一场。", "speaker": "大人", "tone": "责备", "sound": []}, {"ts": "00:04:03", "text": "这幅画和前几个一样也被拒绝了。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "这只太老了。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "我想要一只能活得长的羊。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "我不耐烦了。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "因为我急于要减修发动机。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "于是嘲嘲地。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "画了这张画。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "对他说到。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "这是一个盒子。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "你要的羊就在里面。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "当时我十分惊奇的。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "看到我的这位小平凡人。", "speaker": "大人", "tone": "宠溺", "sound": []}, {"ts": "00:04:03", "text": "洗笑眼睛。", "speaker": "大人", "tone": "宠溺", "sound": []}, {"ts": "00:04:03", "text": "他说。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "这真是我想要的。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "你说这只羊需要很多草吗？", "speaker": "大人", "tone": "询问", "sound": []}, {"ts": "00:04:03", "text": "为什么？", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "问这个呢？", "speaker": "大人", "tone": "询问", "sound": []}, {"ts": "00:04:03", "text": "因为我那里非常的小。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "我给你画的是一只很小的羊。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "地方小也能够喂养他的。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "他把脑袋靠近这张画。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "并不像你说的那么小。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "脚。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "他睡著了。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "就这样。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "我认识了小王子。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "晚安。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "宝贝。", "speaker": "大人", "tone": "撒娇", "sound": []}, {"ts": "00:04:03", "text": "开场贝贝。", "speaker": "大人", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "睡觉家了。", "speaker": "大人", "tone": "平静", "sound": []}], "scene": "朗读类（文学有声书）。叙述者回忆飞机坠毁撒哈拉沙漠、孤身维羞的处境，以及一个奇怪的小孩（小王子）出现，反复要求他画一只羊。经过多次尝试与拒绝，叙述者最终画了一个盒子说羊在里面，小王子满意。基调奇遇、童趣，主题为相遇与纯真。无亲密或惩罚情节。", "behaviors": [{"desc": "叙述者回忆飞机坠毁沙漠、孤身面对维修与孤独"}, {"desc": "小王子出现，要求叙述者为他画一只羊"}, {"desc": "叙述者多次尝试画羊，小王子逐一拒绝并说明原因"}, {"desc": "叙述者画盒子说羊在里面，小王子满意；以晚安宝贝收尾"}], "tone_summary": "（自动）大人视角独白，语气以平静、宠溺、命令为主，题材偏现代情侣。", "genre_tags": ["现代情侣"], "genre_main": "现代情侣", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被大人倾诉/照顾/管教的一方（你）", "signature_elements": [], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "我就这样孤独地生活着，没有一个能真正谈得来的人。一直到六年前，在撒哈拉沙漠上发生那次事故：我的发动机里有个东西损坏了。由于我既没有带机械师，也没有带旅客，我就试图独自完成这个困难的维修工作。这对我来说，是个生死攸关的问题。"}, {"type": "narr", "text": "我随身带的水只够喝一个星期。第一天晚上，我就睡在这远离人间烟火的大沙漠上。我比大海中附在小木牌上的遇难者还要孤独很多。而第二天拂晓，当一个奇怪的小声音叫醒我的时候，你们可以想见我当时多么吃惊。"}, {"type": "line", "speaker": "小王子", "text": "请你给我画一只山羊好吗？"}, {"type": "line", "speaker": "小王子", "text": "给我画一只羊。"}, {"type": "narr", "text": "我像是受到了惊雷的轰击一样，一下子就站了起来。我使劲地揉了揉眼睛，仔细地看了看。我看见一个十分奇怪的小家伙，严肃地朝我凝望着。"}, {"type": "narr", "text": "这是后来我给他画出来的最好的画像。可是我的话，当然要比他本人的模样逊色很多。这不是我的过错——六岁的时候，大人们使我对画画儿的生涯失去了勇气，除了画过开着肚皮和闭着肚皮的蟒蛇，后来我再没有学过画。"}, {"type": "narr", "text": "我惊奇地瞪大眼看着这突然出现的小家伙。你们不要忘记，我当时是处在远离人间千里之外的地方。而这个小家伙给我的印象是：他既不像迷了路的样子，也没有半点疲乏、饥渴、惧怕的神情。他似乎不像是一个迷失在大沙漠中的孩子。"}, {"type": "narr", "text": "当我在惊讶之中终于能说出话来的时候，对他说："}, {"type": "line", "speaker": "我", "text": "你在这儿干什么？"}, {"type": "narr", "text": "可是他却不慌不忙的，好像有一件重要的事情一般，对我重复说道："}, {"type": "line", "speaker": "小王子", "text": "请你给我画一只山羊。"}, {"type": "narr", "text": "当一种神秘的东西把你震慑住的时候，你是不敢不听从它的支配的。在这杳无人烟的沙漠上，面临死亡危险的情况下，尽管这样的举动让我觉得十分荒诞，但我还是掏出了纸和笔。"}, {"type": "narr", "text": "可是我记起，我只学过地理、历史、算术和语法，就有点不太开心地对小家伙说我不会画画。"}, {"type": "line", "speaker": "小王子", "text": "没有关系。给我画一只羊吧。"}, {"type": "narr", "text": "因为我从来没有画过羊，我就给他画了我仅仅会画的两幅画中的一幅——那幅闭着肚皮的蟒蛇。"}, {"type": "line", "speaker": "小王子", "text": "不，不，不要蟒蛇。他肚子里还有一头大象。"}, {"type": "narr", "text": "我听了他的话，简直目瞪口呆。他接着说："}, {"type": "line", "speaker": "小王子", "text": "蟒蛇这东西太危险了。大象又太占地方。我住的地方非常小。我需要一只羊。给我画一只羊吧。"}, {"type": "narr", "text": "于是我就给他画了。他专心地看着，最后又说："}, {"type": "line", "speaker": "小王子", "text": "我不要。这只羊已经病得很重了。给我重新画一只。"}, {"type": "narr", "text": "我又画了起来。我的这位朋友天真可爱地笑了，并且客气地拒绝道："}, {"type": "line", "speaker": "小王子", "text": "你看，你画的不是小羊，是头公羊，还有犄角呢。"}, {"type": "narr", "text": "于是我又重新画了一张。这幅画和前几幅一样，也被拒绝了。"}, {"type": "line", "speaker": "小王子", "text": "这只太老了。我想要一只能活得长的羊。"}, {"type": "narr", "text": "我不耐烦了，因为我急于要拆修发动机。于是我就草草地画了这张画，对他说道："}, {"type": "line", "speaker": "我", "text": "这是一个盒子。你要的羊就在里面。"}, {"type": "narr", "text": "当时我十分惊奇地看到，我的这位小评判员笑逐颜开。他说："}, {"type": "line", "speaker": "小王子", "text": "这真是我想要的。你说这只羊需要很多草吗？"}, {"type": "narr", "text": "我问他为什么问这个。"}, {"type": "line", "speaker": "小王子", "text": "因为我那里非常的小。"}, {"type": "line", "speaker": "我", "text": "我给你画的是一只很小的羊，地方小也能够喂养它的。"}, {"type": "narr", "text": "他把脑袋靠近这张画。并不像你说的那么小。瞧，它睡着了。就这样，我认识了小王子。"}, {"type": "narr", "text": "晚安，宝贝。"}]}]);